/**
 * loggerService.ts — Layanan penangkap dan penyimpan log diagnostik in-memory
 *
 * Menangkap log console, unhandled rejection, error runtime, interaksi klik pengguna,
 * dan OfficeExtension.Error agar setiap tindakan dan error terekam jelas di riwayat log.
 */

export interface LogEntry {
  id: string;
  time: string;
  level: "info" | "warn" | "error";
  message: string;
  stack?: string;
}

class LoggerService {
  private logs: LogEntry[] = [];
  private maxLogs = 500;
  private listeners: Set<() => void> = new Set();
  private initialized = false;

  constructor() {
    this.init();
  }

  public init() {
    if (this.initialized || typeof window === "undefined") return;
    this.initialized = true;

    // 1. Tangkap console logs
    const origLog = console.log.bind(console);
    const origWarn = console.warn.bind(console);
    const origError = console.error.bind(console);

    console.log = (...args: unknown[]) => {
      origLog(...args);
      this.addEntry("info", this.formatArgs(args));
    };

    console.warn = (...args: unknown[]) => {
      origWarn(...args);
      this.addEntry("warn", this.formatArgs(args));
    };

    console.error = (...args: unknown[]) => {
      origError(...args);
      const stack = args.find((a) => a instanceof Error) as Error | undefined;
      this.addEntry("error", this.formatArgs(args), stack?.stack);
    };

    // 2. Tangkap uncaught window errors & promise rejections
    window.addEventListener("error", (event: ErrorEvent) => {
      this.addEntry(
        "error",
        `Uncaught error: ${event.message} (${event.filename}:${event.lineno}:${event.colno})`,
        event.error?.stack
      );
    });

    window.addEventListener("unhandledrejection", (event: PromiseRejectionEvent) => {
      this.logError("UnhandledPromiseRejection", event.reason);
    });

    // 3. Tangkap setiap interaksi klik pengguna (Capture Phase)
    document.addEventListener(
      "click",
      (event: MouseEvent) => {
        try {
          const target = event.target as HTMLElement | null;
          if (!target) return;

          // Jangan catat klik di dalam dialog log itu sendiri untuk menghindari spam
          if (target.closest(".log-dialog-surface")) return;

          // Cari elemen interaktif terdekat
          const el = (target.closest(
            "button, a, input, select, [role='button'], [role='tab'], [role='radio'], [role='checkbox'], [tabindex]"
          ) || target) as HTMLElement;

          const tag = el.tagName.toLowerCase();
          const role = el.getAttribute("role") ? ` [role=${el.getAttribute("role")}]` : "";
          const id = el.id ? ` #${el.id}` : "";

          // Ekstrak label atau teks elemen
          let label =
            el.getAttribute("aria-label") ||
            el.getAttribute("title") ||
            (el as HTMLInputElement).value ||
            el.innerText ||
            "";

          label = label.replace(/\s+/g, " ").trim().slice(0, 60);

          this.addEntry(
            "info",
            `[User Click] <${tag}${id}${role}> "${label || "(elemen tanpa teks)"}"`
          );
        } catch {
          // Abaikan error saat mencatat klik
        }
      },
      true
    );

    // 4. Tangkap event perubahan input/select
    document.addEventListener(
      "change",
      (event: Event) => {
        try {
          const target = event.target as HTMLInputElement | HTMLSelectElement | null;
          if (!target || target.closest(".log-dialog-surface")) return;

          const tag = target.tagName.toLowerCase();
          const name = target.name || target.id || target.getAttribute("aria-label") || "";
          const val = target.type === "checkbox" ? target.checked : target.value;

          this.addEntry("info", `[User Change] <${tag}> ${name ? `"${name}"` : ""} => ${String(val)}`);
        } catch {
          // Abaikan
        }
      },
      true
    );

    this.addEntry("info", "Excel Print Studio Logger initialized.");
  }

  private formatArgs(args: unknown[]): string {
    return args
      .map((arg) => {
        if (arg === null) return "null";
        if (arg === undefined) return "undefined";
        if (typeof arg === "object") {
          try {
            return JSON.stringify(arg);
          } catch {
            return String(arg);
          }
        }
        return String(arg);
      })
      .join(" ");
  }

  public addEntry(level: "info" | "warn" | "error", message: string, stack?: string) {
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, "0")}:${now
      .getMinutes()
      .toString()
      .padStart(2, "0")}:${now.getSeconds().toString().padStart(2, "0")}.${now
      .getMilliseconds()
      .toString()
      .padStart(3, "0")}`;

    const entry: LogEntry = {
      id: Math.random().toString(36).substring(2, 9),
      time,
      level,
      message,
      stack,
    };

    this.logs.push(entry);
    if (this.logs.length > this.maxLogs) {
      this.logs.shift();
    }

    this.notify();
  }

  /**
   * Catat error dengan detail komprehensif (termasuk OfficeExtension.Error).
   */
  public logError(source: string, error: unknown) {
    let message = "";
    let stack: string | undefined;

    if (error && typeof error === "object") {
      const err = error as Record<string, any>;
      // Deteksi OfficeExtension.Error (Excel.js)
      if (err.debugInfo || err.code) {
        const code = err.code || "OfficeError";
        const msg = err.message || "";
        const location = err.debugInfo?.errorLocation ? ` at ${err.debugInfo.errorLocation}` : "";
        const statement = err.debugInfo?.statement ? `\n  Statement: ${err.debugInfo.statement}` : "";
        const surrounding = err.debugInfo?.surroundingStatements
          ? `\n  Surrounding: ${JSON.stringify(err.debugInfo.surroundingStatements)}`
          : "";

        message = `[${source}] OfficeExtension.Error (${code}${location}): ${msg}${statement}${surrounding}`;
        stack = err.stack;
      } else if (err instanceof Error) {
        message = `[${source}] Error: ${err.message}`;
        stack = err.stack;
      } else {
        message = `[${source}] Object: ${JSON.stringify(err)}`;
      }
    } else {
      message = `[${source}] ${String(error || "Unknown error")}`;
    }

    this.addEntry("error", message, stack);
  }

  public logAction(action: string, detail?: string) {
    this.addEntry("info", `[Action] ${action}${detail ? `: ${detail}` : ""}`);
  }

  public getLogs(): LogEntry[] {
    return [...this.logs];
  }

  public getErrorCount(): number {
    return this.logs.filter((l) => l.level === "error").length;
  }

  public clear() {
    this.logs = [];
    this.notify();
  }

  public subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private notify() {
    for (const listener of this.listeners) {
      try {
        listener();
      } catch {
        // Abaikan
      }
    }
  }

  public getDiagnostics(): string {
    const lines: string[] = [
      "=== DIAGNOSTIK EXCEL PRINT STUDIO ===",
      `Waktu: ${new Date().toISOString()}`,
      `URL: ${typeof window !== "undefined" ? window.location.href : "N/A"}`,
      `User Agent: ${typeof navigator !== "undefined" ? navigator.userAgent : "N/A"}`,
      `Office.js Terpasang: ${typeof Office !== "undefined" ? "Ya" : "Tidak"}`,
    ];

    if (typeof Office !== "undefined" && Office.context) {
      lines.push(`Office Host: ${Office.context.host || "Unknown"}`);
      lines.push(`Office Platform: ${Office.context.platform || "Unknown"}`);
      if (Office.context.diagnostics) {
        lines.push(`Diagnostics Host: ${Office.context.diagnostics.host}`);
        lines.push(`Diagnostics Version: ${Office.context.diagnostics.version}`);
        lines.push(`Diagnostics Platform: ${Office.context.diagnostics.platform}`);
      }
      if (Office.context.requirements) {
        try {
          const api19 = Office.context.requirements.isSetSupported("ExcelApi", "1.9");
          const api110 = Office.context.requirements.isSetSupported("ExcelApi", "1.10");
          lines.push(`Support ExcelApi 1.9: ${api19}`);
          lines.push(`Support ExcelApi 1.10: ${api110}`);
        } catch {
          // Abaikan
        }
      }
    }

    return lines.join("\n");
  }

  public exportFullLog(): string {
    const diag = this.getDiagnostics();
    const logLines = this.logs.map((l) => {
      let str = `[${l.time}] [${l.level.toUpperCase()}] ${l.message}`;
      if (l.stack) {
        str += `\n  Stack: ${l.stack}`;
      }
      return str;
    });

    return `${diag}\n\n=== RIWAYAT LOG (${this.logs.length} ENTRI) ===\n${logLines.join("\n")}`;
  }
}

export const logger = new LoggerService();
