/**
 * excelService.ts — Layer akses Office.js
 *
 * Semua interaksi dengan Excel API dibungkus di sini.
 * UI tidak langsung memanggil Excel.run atau Office.context.
 * Ref: spesifikasi §4, PRD §6
 */

import type { PlatformCapabilities } from "@shared/types";
import { isStagingSheet } from "@shared/utils";
import { logger } from "./loggerService";

// ─── Platform detection ───────────────────────────────────────────

/**
 * Deteksi kapabilitas platform saat ini.
 * Harus dipanggil setelah Office.onReady().
 */
export function detectPlatform(): PlatformCapabilities {
  const hasPageLayout = Office.context.requirements.isSetSupported("ExcelApi", "1.9");
  const hasPdfExport = Office.context.requirements.isSetSupported("PdfFile", "1.1");
  const hasDialog = Office.context.requirements.isSetSupported("DialogApi", "1.1");

  let platform = "Unknown";
  if (Office.context.platform) {
    platform = Office.context.platform.toString();
  }

  return { hasPageLayout, hasPdfExport, hasDialog, platform };
}

// ─── Seleksi aktif ────────────────────────────────────────────────

export interface SelectionInfo {
  sheetId: string;
  sheetName: string;
  address: string;
  /** Lebar range dalam poin (memerlukan ExcelApi 1.10) */
  widthPoints?: number;
  /** Tinggi range dalam poin (memerlukan ExcelApi 1.10) */
  heightPoints?: number;
  /** Jumlah sel */
  cellCount?: number;
  /** Edge case: apakah sheet diproteksi */
  isProtected?: boolean;
  /** Edge case: apakah workbook read-only */
  isReadOnly?: boolean;
  /** Edge case: apakah range mengandung sel gabungan */
  hasMergedCells?: boolean;
  /** Edge case: apakah ada baris/kolom tersembunyi */
  hasHiddenCells?: boolean;
  /** Edge case: apakah range > 100.000 sel */
  isTooLarge?: boolean;
}

/**
 * Ambil informasi seleksi aktif dari workbook beserta deteksi edge case.
 * Mengembalikan null jika tidak ada seleksi.
 */
export async function getSelectedRange(): Promise<SelectionInfo | null> {
  return Excel.run(async (context) => {
    const range = context.workbook.getSelectedRange();
    const sheet = range.worksheet;
    const workbook = context.workbook;

    range.load("address, cellCount");
    sheet.load("id, name, protection/protected");
    workbook.load("readOnly");

    // Coba muat width/height jika API 1.10 tersedia
    const hasSize = Office.context.requirements.isSetSupported("ExcelApi", "1.10");
    if (hasSize) {
      range.load("width, height");
    }

    // Deteksi merged cells jika didukung
    let mergedAreas: Excel.RangeAreas | null = null;
    try {
      mergedAreas = range.getMergedAreasOrNullObject();
      mergedAreas.load("isNullObject, areaCount");
    } catch {
      // Abaikan jika tidak didukung platform
    }

    // Deteksi visible cells jika didukung
    let visibleCells: Excel.RangeAreas | null = null;
    try {
      visibleCells = range.getSpecialCellsOrNullObject(Excel.SpecialCellType.visible);
      visibleCells.load("isNullObject, cellCount");
    } catch {
      // Abaikan jika tidak didukung platform
    }

    await context.sync();

    const isProtected = Boolean(sheet.protection?.protected);
    const isReadOnly = Boolean(workbook.readOnly);
    const cellCount = range.cellCount ?? 0;
    const isTooLarge = cellCount > 100000;
    const hasMergedCells = Boolean(
      mergedAreas && !mergedAreas.isNullObject && mergedAreas.areaCount > 0
    );
    const hasHiddenCells = Boolean(
      visibleCells && !visibleCells.isNullObject && visibleCells.cellCount < cellCount
    );

    return {
      sheetId: sheet.id,
      sheetName: sheet.name,
      address: range.address.includes("!") ? range.address.split("!")[1] : range.address,
      widthPoints: hasSize ? (range as any).width : undefined,
      heightPoints: hasSize ? (range as any).height : undefined,
      cellCount,
      isProtected,
      isReadOnly,
      hasMergedCells,
      hasHiddenCells,
      isTooLarge,
    };
  });
}

/**
 * Ukur dimensi konten (dalam poin) untuk beberapa halaman secara batch dengan 1 kali sync.
 * Ref: PRD §4 Fitur 2E, NF2
 */
export async function getAllRangesDimensions(
  pages: Array<{ sheetName: string; address: string }>
): Promise<Array<{ widthPt: number; heightPt: number }>> {
  if (pages.length === 0) return [];

  try {
    return await Excel.run(async (context) => {
      const hasSize = Office.context.requirements.isSetSupported("ExcelApi", "1.10");
      const rangeItems = pages.map((page) => {
        const cleanAddress = page.address.includes("!") ? page.address.split("!")[1] : page.address;
        const sheet = context.workbook.worksheets.getItem(page.sheetName);
        const range = sheet.getRange(cleanAddress);
        if (hasSize) {
          range.load("width, height");
        } else {
          range.load("rowCount, columnCount");
        }
        return { range, page };
      });

      await context.sync();

      return rangeItems.map(({ range }) => {
        if (hasSize) {
          const w = (range as any).width;
          const h = (range as any).height;
          if (typeof w === "number" && typeof h === "number" && w > 0 && h > 0) {
            return { widthPt: w, heightPt: h };
          }
        }
        // Fallback: estimasi kolom (64pt) & baris (20pt)
        const cols = (range as any).columnCount ?? 8;
        const rows = (range as any).rowCount ?? 30;
        return {
          widthPt: Math.max(50, cols * 64),
          heightPt: Math.max(50, rows * 20),
        };
      });
    });
  } catch (err) {
    logger.logError("getAllRangesDimensions", err);
    return pages.map(() => ({ widthPt: 500, heightPt: 700 }));
  }
}

// ─── Sheet operations ─────────────────────────────────────────────

export type SheetVisibilityValue = Excel.SheetVisibility | "Visible" | "Hidden" | "VeryHidden";

export interface SheetVisibilityState {
  id: string;
  name: string;
  visibility: SheetVisibilityValue;
}

/**
 * Simpan state visibilitas semua sheet.
 */
export async function saveSheetVisibility(): Promise<SheetVisibilityState[]> {
  return Excel.run(async (context) => {
    const sheets = context.workbook.worksheets;
    sheets.load("items/id, items/name, items/visibility");
    await context.sync();

    return sheets.items.map((s) => ({
      id: s.id,
      name: s.name,
      visibility: s.visibility,
    }));
  });
}

/**
 * Pulihkan state visibilitas sheet.
 */
export async function restoreSheetVisibility(states: SheetVisibilityState[]): Promise<void> {
  await Excel.run(async (context) => {
    const sheets = context.workbook.worksheets;
    sheets.load("items/id");
    await context.sync();

    for (const state of states) {
      try {
        const sheet = sheets.items.find((s) => s.id === state.id);
        if (sheet) {
          sheet.visibility = state.visibility;
        }
      } catch {
        // Sheet mungkin sudah dihapus
      }
    }
    await context.sync();
  });
}

/**
 * Simpan dan kembalikan sheet aktif dan seleksi.
 */
export async function getActiveSheetInfo(): Promise<{ sheetId: string; selection: string }> {
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const range = context.workbook.getSelectedRange();
    sheet.load("id");
    range.load("address");
    await context.sync();
    return { sheetId: sheet.id, selection: range.address };
  });
}

/**
 * Deteksi sheet staging sisa dari sesi sebelumnya.
 */
export async function findLeftoverStagingSheets(): Promise<string[]> {
  return Excel.run(async (context) => {
    const sheets = context.workbook.worksheets;
    sheets.load("items/name");
    await context.sync();
    return sheets.items.filter((s) => isStagingSheet(s.name)).map((s) => s.name);
  });
}

/**
 * Hapus sheet staging berdasarkan nama.
 */
export async function deleteStagingSheets(names: string[]): Promise<void> {
  if (names.length === 0) return;

  await Excel.run(async (context) => {
    for (const name of names) {
      try {
        const sheet = context.workbook.worksheets.getItem(name);
        sheet.delete();
      } catch {
        // Sheet mungkin sudah tidak ada
      }
    }
    await context.sync();
  });
}

/**
 * Validasi bahwa sebuah sheet + range masih valid.
 */
export async function validateSheetRange(
  sheetId: string,
  address: string
): Promise<{ valid: boolean; error?: string }> {
  try {
    return await Excel.run(async (context) => {
      const sheets = context.workbook.worksheets;
      sheets.load("items/id, items/name");
      await context.sync();

      const sheet = sheets.items.find((s) => s.id === sheetId);
      if (!sheet) {
        return { valid: false, error: "Sheet tidak ditemukan (mungkin sudah dihapus)." };
      }

      try {
        const range = sheet.getRange(address);
        range.load("address");
        await context.sync();
        return { valid: true };
      } catch {
        return { valid: false, error: `Range ${address} tidak valid di sheet "${sheet.name}".` };
      }
    });
  } catch {
    return { valid: false, error: "Gagal mengakses workbook." };
  }
}

// ─── PDF export ───────────────────────────────────────────────────

/**
 * Ekspor workbook sebagai PDF (seluruh dokumen).
 * Mengembalikan Uint8Array berisi data PDF.
 */
export function exportPdf(): Promise<Uint8Array> {
  return new Promise((resolve, reject) => {
    logger.addEntry("info", "[exportPdf] Memanggil Office.context.document.getFileAsync(Pdf)...");

    if (!Office.context.document || !Office.context.document.getFileAsync) {
      const err = new Error("Office.context.document.getFileAsync tidak didukung pada lingkungan ini.");
      logger.logError("exportPdf", err);
      reject(err);
      return;
    }

    Office.context.document.getFileAsync(
      Office.FileType.Pdf,
      { sliceSize: 65536 },
      async (result) => {
        if (result.status === Office.AsyncResultStatus.Failed) {
          const errDetail = `[Code: ${result.error?.code || "N/A"}] ${result.error?.message || "Gagal membuat PDF"}`;
          logger.addEntry("error", `[exportPdf GAGAL] getFileAsync gagal: ${errDetail}`);
          reject(new Error(errDetail));
          return;
        }

        const file = result.value;
        const sliceCount = file.sliceCount;
        logger.addEntry("info", `[exportPdf] getFileAsync berhasil, total slice: ${sliceCount}`);
        const slices: Uint8Array[] = [];

        try {
          for (let i = 0; i < sliceCount; i++) {
            const sliceData = await getSlice(file, i);
            slices.push(new Uint8Array(sliceData));
          }

          // Gabungkan semua slice
          const totalLength = slices.reduce((sum, s) => sum + s.length, 0);
          const pdf = new Uint8Array(totalLength);
          let offset = 0;
          for (const slice of slices) {
            pdf.set(slice, offset);
            offset += slice.length;
          }

          file.closeAsync();
          logger.addEntry("info", `[exportPdf] Selesai membaca ${sliceCount} slices. Total: ${totalLength} bytes.`);
          resolve(pdf);
        } catch (err) {
          file.closeAsync();
          logger.logError("exportPdf.getSlice", err);
          reject(err);
        }
      }
    );
  });
}

function getSlice(file: Office.File, index: number): Promise<ArrayBuffer> {
  return new Promise((resolve, reject) => {
    file.getSliceAsync(index, (result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        const msg = `Slice ${index} gagal: [${result.error?.code}] ${result.error?.message}`;
        logger.addEntry("error", `[exportPdf.getSlice] ${msg}`);
        reject(new Error(msg));
      } else {
        resolve(result.value.data);
      }
    });
  });
}

// ─── Dialog ───────────────────────────────────────────────────────

/**
 * Buka dialog untuk pratinjau PDF penuh.
 * @param url URL dialog (dialog.html)
 * @param width Persentase lebar (default 80%)
 * @param height Persentase tinggi (default 80%)
 */
export function openDialog(
  url: string,
  width: number = 80,
  height: number = 80
): Promise<Office.Dialog> {
  return new Promise((resolve, reject) => {
    Office.context.ui.displayDialogAsync(
      url,
      { width, height, displayInIframe: false },
      (result) => {
        if (result.status === Office.AsyncResultStatus.Failed) {
          reject(new Error(result.error.message));
        } else {
          resolve(result.value);
        }
      }
    );
  });
}
